laboratory.referenceCode:
#include <iostream>

int main() {
    int stock{12};
    int beforeSale = stock;
    std::cout << "before=" << beforeSale << '\n';
    {
        const int sold{5};
        stock = stock - sold;
        std::cout << "inside=" << stock << '\n';
    }
    std::cout << "after=" << stock << '\n';
    std::cout << "snapshot=" << beforeSale << '\n';
    return 0;
}
